# awk conformance cases, sourced by tests/run.sh. The reference is
# `gawk --posix` through a wrapper named awk on the reference PATH.
mkdir -p "$W/refbin"
printf '#!/bin/sh\nexec gawk --posix "$@"\n' > "$W/refbin/awk"
chmod +x "$W/refbin/awk"
REFPATH="$W/refbin:"

printf 'alice eng 100\nbob ops 80\ncarol eng 120\ndave ops 90\nerin qa 70\n' > "$W/fixture/emp.txt"
printf 'id,name,qty\n1,apple,3\n2,pear,\n3,fig,10\n' > "$W/fixture/sales.csv"
printf 'para one\nline two\n\n\npara two\n\nlast para\nend\n' > "$W/fixture/paras.txt"
printf 'k1 v1\nk2 v2\nk3 v3\n' > "$W/fixture/left.txt"
printf 'k2 w2\nk3 w3\nk4 w4\nk1 w1\n' > "$W/fixture/right.txt"

# programs, options, operands
same awk-print0 "awk '{ print }' words.txt"
same awk-pattern-only "awk '/a/' words.txt"
